import os, re
from collections import Counter

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

def analyze_grid(name):
    for m in re.finditer(rf'{name} \((\d+)x(\d+)\):\n', t):
        h, w = int(m.group(1)), int(m.group(2))

        # Get raw text after this marker
        raw_text = t[m.end():]
        lines = raw_text.split('\n')[:h+5]  # Extra to find where grid ends

        # Find where grid actually ends by looking for non-integer lines
        grid_lines = []
        for line in lines:
            line_stripped = line.strip()
            if not line_stripped:
                continue
            try:
                parts = [int(x) for x in line_stripped.split()]
                if len(parts) == w:
                    grid_lines.append(line_stripped)
                else:
                    break  # Not a grid row anymore
            except ValueError:
                break  # Non-integer found, grid ended

        grid = [[int(x) for x in line.split()] for line in grid_lines]

        counts = Counter(c for row in grid for c in row)
        bg, spec = sorted(counts.items(), key=lambda x: x[1], reverse=True)[0][0], sorted(counts.items(), key=lambda x: x[1], reverse=True)[-1][0]

        rows, cols = len(grid), len(grid[0])
        visited = set()
        def get_neighbors(r, c):
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if 0<=nr<rows and 0<=nc<cols and grid[nr][nc]==spec and (nr,nc) not in visited:
                    yield nr, nc

        components = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == spec and (r,c) not in visited:
                    comp = []
                    queue = [(r,c)]
                    visited.add((r,c))
                    while queue:
                        cr, cc = queue.pop(0)
                        comp.append((cr,cc))
                        for nr, nc in get_neighbors(cr, cc):
                            visited.add((nr,nc))
                            queue.append((nr,nc))
                    components.append(comp)

        sizes = [len(c) for c in components]
        max_size = max(sizes) if sizes else 0
        avg_size = sum(sizes)/len(sizes) if sizes else 0

        total_pairs = 0
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == spec:
                    if c+1 < cols and grid[r][c+1] == spec:
                        total_pairs += 1
                    if r+1 < rows and grid[r+1][c] == spec:
                        total_pairs += 1

        print(f"\n{name}:")
        print(f"  Size: {h}x{w} = {h*w} cells")
        print(f"  Counts: {dict(counts)}")
        print(f"  bg={bg}, spec={spec}")
        num_spec = sum(1 for row in grid for cell in row if cell==spec)
        print(f"  Special pixels: {num_spec}")
        print(f"  #components: {len(components)}, max_size={max_size}, avg_size={avg_size:.1f}")
        print(f"  Adjacent pairs: {total_pairs}")

analyze_grid('Demo pair 1 input')
analyze_grid('Demo pair 2 input')
analyze_grid('Test input')

